TLM.f("Tempora/Adv2-2",{"officium":"Feria III infra Hebdomadam II Adventus","rule":["Oratio Dominica","no Gloria","no Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"ruleInherited":["no Gloria","Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"fallback":"Tempora/Adv2-0","from":{"Introitus":"Tempora/Adv2-0","Oratio":"Tempora/Adv2-0","Lectio":"Tempora/Adv2-0","Graduale":"Tempora/Adv2-0","GradualeF":"Tempora/Adv2-0","Evangelium":"Tempora/Adv2-0","Offertorium":"Tempora/Adv2-0","Secreta":"Tempora/Adv2-0","Communio":"Tempora/Adv2-0","Postcommunio":"Tempora/Adv2-0"},"sections":{"Introitus":[{"k":"ref","la":"Is 30:30"},{"k":"text","la":"Pópulus Sion, ecce, Dóminus véniet ad salvándas gentes: et audítam fáciet Dóminus glóriam vocis suæ in lætítia cordis vestri."},{"k":"ref","la":"Ps 79:2"},{"k":"text","la":"Qui regis Israël, inténde: qui dedúcis, velut ovem, Joseph."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Pópulus Sion, ecce, Dóminus véniet ad salvándas gentes: et audítam fáciet Dóminus glóriam vocis suæ in lætítia cordis vestri."}],"Oratio":[{"k":"text","la":"Excita, Dómine, corda nostra ad præparándas Unigéniti tui vias: ut, per ejus advéntum, purificátis tibi méntibus servíre mereámur:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Lectio Epístolæ beáti Pauli Apostoli ad Romános"},{"k":"ref","la":"Rom 15:4-13"},{"k":"text","la":"Fratres: Quæcúmque scripta sunt, ad nostram doctrínam scripta sunt: ut per patiéntiam et consolatiónem Scripturárum spem habeámus. Deus autem patiéntiæ et solácii det vobis idípsum sápere in altérutrum secúndum Jesum Christum: ut unánimes, uno ore honorificétis Deum et Patrem Dómini nostri Jesu Christi. Propter quod suscípite ínvicem, sicut et Christus suscépit vos in honórem Dei. Dico enim Christum Jesum minístrum fuísse circumcisiónis propter veritátem Dei, ad confirmándas promissiónes patrum: gentes autem super misericórdia honoráre Deum, sicut scriptum est: Proptérea confitébor tibi in géntibus, Dómine, et nómini tuo cantábo. Et íterum dicit: Lætámini, gentes, cum plebe ejus. Et iterum: Laudáte, omnes gentes, Dóminum: et magnificáte eum, omnes pópuli. Et rursus Isaías ait: Erit radix Jesse, et qui exsúrget régere gentes, in eum gentes sperábunt. Deus autem spei répleat vos omni gáudio et pace in credéndo: ut abundétis in spe et virtúte Spíritus Sancti."}],"Graduale":[{"k":"ref","la":"Ps 49:2-3; 49:5"},{"k":"text","la":"Ex Sion species decóris ejus: Deus maniféste véniet,"},{"k":"text","la":"Congregáte illi sanctos ejus, qui ordinavérunt testaméntum ejus super sacrifícia. Allelúja, allelúja,","mark":"V"},{"k":"ref","la":"Ps 121:1"},{"k":"text","la":"Lætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus. Allelúja.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 49:2-3; 49:5"},{"k":"text","la":"Ex Sion species decóris ejus: Deus maniféste véniet,"},{"k":"text","la":"Congregáte illi sanctos ejus, qui ordinavérunt testaméntum ejus super sacrifícia.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 11:2-10"},{"k":"text","la":"In illo tempore: Cum audísset Joánnes in vínculis ópera Christi, mittens duos de discípulis suis, ait illi: Tu es, qui ventúrus es, an alium exspectámus? Et respóndens Jesus, ait illis: Eúntes renuntiáte Joánni, quæ audístis et vidístis. Cæci vident, claudi ámbulant, leprósi mundántur, surdi áudiunt, mórtui resúrgunt, páuperes evangelizántur: et beátus est, qui non fúerit scandalizátus in me. Illis autem abeúntibus, cœpit Jesus dícere ad turbas de Joánne: Quid exístis in desértum vidére? arúndinem vento agitátam? Sed quid exístis vidére? hóminem móllibus vestitum? Ecce, qui móllibus vestiúntur, in dómibus regum sunt. Sed quid exístis vidére? Prophétam? Etiam dico vobis, et plus quam Prophétam. Hic est enim, de quo scriptum est: Ecce, ego mitto Angelum meum ante fáciem tuam, qui præparábit viam tuam ante te."}],"Offertorium":[{"k":"ref","la":"Ps 84:7-8"},{"k":"text","la":"Deus, tu convérsus vivificábis nos, et plebs tua lætábitur in te: osténde nobis, Dómine, misericórdiam tuam, et salutáre tuum da nobis."}],"Secreta":[{"k":"text","la":"Placáre, quǽsumus, Dómine, humilitátis nostræ précibus et hóstiis: et, ubi nulla suppétunt suffrágia meritórum, tuis nobis succúrre præsídiis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Bar 5:5; 4:36"},{"k":"text","la":"Jerúsalem, surge et sta in excélso, et vide jucunditátem, quæ véniet tibi a Deo tuo."}],"Postcommunio":[{"k":"text","la":"Repléti cibo spirituális alimóniæ, súpplices te, Dómine, deprecámur: ut, hujus participatióne mystérii, dóceas nos terréna despícere et amáre cœléstia."},{"k":"macro","name":"Per Dominum"}]},"hr":{"87a652f68a979314":{"t":"<i>Pomolimo se</i>.\nPotakni, Gospodine, naša srca da pripreme putove Jedinorođenom Sinu tvomu, te budemo dostojni tebi služiti očišćene duše dolaskom onoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e15aa366a18db18":{"t":"Neka te umilostive, Gospodine, naše smjerne molitve i prinosi, i budući da nemamo nikakvih vlastitih zasluga, ti nam priteci u pomoć svojom zaštitom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"a937596817bd89ba":{"t":"<i>Pomolimo se</i>.\nNasićeni duhovnom hranom smjerno te molimo, Gospodine, da nas učešćem u ovom otajstvu naučiš prezirati što je zemaljsko, a ljubiti što je nebesko.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"582b9d35435b11ff":{"t":"Iz 30, 30; Ps 79, 2\n(Iz 30, 30) Puče sionski, evo Gospodin će doći da spasi narode i objavit će se Gospodin svojim slavnim glasom na veselje vašega srca. (Ps 79, 2) Čuj, vladaru Izraelov, koji vodiš Josipovo pleme kao stado.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nPuče sionski, evo Gospodin će doći da spasi narode i objavit će se Gospodin svojim slavnim glasom na veselje vašega srca."},"80953796092f42a0":{"t":"Rim 15, 4-13\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: što god je pisano, napisano je za pouku nama da se učvrstimo u nadi, okrijepljeni i utješeni Svetim Pismom. Bog strpljivosti i utjehe dao vam da među sobom budete istog mišljenja, jednodušni po Isusu Kristu i da složno slavite Boga i Oca Gospodina našeg Isusa Krista. Zato primajte jedan drugoga, kao što je i Krist primio vas na slavu Božju. Jer kažem da je Isus Krist bio sluga obrezanih radi Božje istinitosti, da potvrdi obećanja dana ocima, a narodi da slave Boga radi milosrđa, kao što piše: »Zato ću te, Gospodine, slaviti među narodima i pjevat ću tvojem imenu.« I ponovo govori: »Veselite se, narodi, s njegovim pukom!« I još: »Hvalite Gospodina svi narodi i uzvisujte ga sva plemena.« A Izaija kaže: »Pojavit će se Jesejev izdanak, i narodi će se uzdati u onoga koji ustaje da vlada narodima.« – Bog nade napunio vas svake radosti i mira u vjeri, da obilujete u nadi i jakosti Duha Svetoga."},"33ed896c460aee7e":{"t":"Ps 49, 2-3,5\nSa Siona sja njegova krasota. Bog će vidljivo doći. Skupite oko njega štovatelje njegove, koji su s njim sklopili žrtveni savez."},"24dd27d7047c0ab4":{"t":"Mt 11, 2-10\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme, kada je Ivan čuo u tamnici za Kristova djela, pošalje dva svoja učenika da ga upitaju: »Jesi li ti onaj koji ima doći, ili da čekamo drugoga?« Isus im odgovori: »Idite i javite Ivanu što čujete i vidite: slijepi vide, hromi hodaju, gubavi se čiste, gluhi čuju, mrtvi ustaju, siromasima se propovijeda evanđelje. I blago onome koji se ne sablazni nada mnom.« – Kad su oni otišli, poče Isus narodu govoriti o Ivanu: »Što ste izašli u pustinju gledati: trsku koju ljulja vjetar? Ili što ste izašli vidjeti: čovjeka obučena u raskošne haljine? Oni koji se raskošno oblače stanuju u kraljevskim dvorima. Ili što ste izašli vidjeti, proroka? Da, kažem vam, i više nego proroka, jer to je onaj o kome je pisano: Evo ja šaljem pred tvojim licem svoga glasnika, da pripravi put pred tobom."},"9251242752ac94bf":{"t":"Ps 84, 7-8\nBože, obazri se na nas i oživi nas, i tvoj će se puk veseliti u tebi. Pokaži nam, Gospodine, milosrđe svoje i spasenje svoje daj nam."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"9b61c73924686e8b":{"t":"Bar 5, 5; 4, 36\nUstani, Jeruzaleme, i stani na visini. Gledaj radost koja će ti doći od Boga tvojega."}}});
